local XUiPBRGeniusPanelGeniusDetail = XClass(XUiNode, "XUiPBRGeniusPanelGeniusDetail")
local XUiPBRGeniusItemGrid = require('XUi/XUiPBRGame/XUiPBRGenius/DetailPanel/XUiPBRGeniusItemGrid')

function XUiPBRGeniusPanelGeniusDetail:InitComponents()
    -- Button
    self.BtnUnlock:AddEventListener(function() self:OnBtnUnlockClick() end)
    self.BtnGet:AddEventListener(function() self:OnBtnGetClick() end)

