end

---@param cfg XTablePBRMetaProgression
function XUiPBRGeniusPanelGeniusDetail:Refresh(nodeId)
    local cfg = self._Control.GeniusControl:GetTablePBRMetaProgressionCfgById(nodeId)
    
    self.TxtName.text = cfg.NodeName
    self.RImgIcon:SetRawImage(cfg.NodeIcon)
    
    self.NodeId = nodeId
    self.IsUnlock = self._Control.GeniusControl:GetIsNodeUnlock(cfg.NodeId)

    if self.IsUnlock then
        -- 已解锁
        self.TxtDetails.text = not string.IsNilOrEmpty(cfg.TextUnlock) and XUiHelper.ReplaceTextNewLine(cfg.TextUnlock) or ''
        self.TxtCondition.gameObject:SetActiveEx(false)
        self.BtnUnlock.gameObject:SetActiveEx(false)
        self.BtnGet.gameObject:SetActiveEx(true)

    else
        self.TxtDetails.text = not string.IsNilOrEmpty(cfg.TextLocked) and XUiHelper.ReplaceTextNewLine(cfg.TextLocked) or ''
        self.BtnUnlock.gameObject:SetActiveEx(true)
        self.BtnGet.gameObject:SetActiveEx(false)
        
        local canUnlock, notDesc = XMVCA.XPBRGame:GetIsNodeCanUnlock(cfg.NodeId)

        if canUnlock then
            self.TxtCondition.gameObject:SetActiveEx(false)
        else
            self.TxtCondition.gameObject:SetActiveEx(true)
            self.TxtCondition.text = notDesc
        end

        self.BtnUnlock:SetButtonState(canUnlock and CS.UiButtonState.Normal or CS.UiButtonState.Disable)
        
        self.IsCanUnlock = canUnlock
        self.NotDesc = notDesc

        -- 未解锁时的解锁花费差异化显示，货币充足和不充足时
        if self._Control.GeniusControl:GetIsNodeHaveEnoughCurrencyToUnlock(cfg.NodeId) then
            self.BtnUnlock:SetNameByGroup(0, XUiHelper.FormatTextEx(self._Control:GetClientPBRText('GeniusCostDesc', 1), cfg.NodeCost))
        else
            self.BtnUnlock:SetNameByGroup(0, XUiHelper.FormatTextEx(self._Control:GetClientPBRText('GeniusCostDesc', 2), cfg.NodeCost))
        end
        
        local itemId = self._Control:GetGeniusCoinItemId()

        if XTool.IsNumberValidEx(itemId) then
            local icon = XItemConfigs.GetItemIconById(itemId)

            if not string.IsNilOrEmpty(icon) then
                self.BtnUnlock:SetRawImage(icon)
            end
        end
    end
    
    
    -- 刷新奖励显示
    if self._RewardShowGridDict == nil then
        self._RewardShowGridDict = {}
    else
        for i, v in pairs(self._RewardShowGridDict) do
            v:Close()
        end
    end
    
    local rewardItemCount = cfg.RewardItemIds and #cfg.RewardItemIds or 0

    if self.PanelObject then
        self.PanelObject.gameObject:SetActiveEx(rewardItemCount > 0)
    end
    
    XUiHelper.RefreshCustomizedList(self.GridItem.transform.parent, self.GridItem, rewardItemCount, function(index, go)
        local grid = self._RewardShowGridDict[go]
        
        if not grid then
            grid = XUiPBRGeniusItemGrid.New(go, self)
            self._RewardShowGridDict[go] = grid
        end
        
        grid:Open()
        grid:RefreshShow(cfg.RewardItemIds[index])
    end)

    -- 奖励标题需要根据是否解锁进行差异化显示
    if self.TxtTips then
        if rewardItemCount > 0 then
            self.TxtTips.gameObject:SetActiveEx(true)
            self.TxtTips.text = self._Control:GetClientPBRText('GeniusRewardTitleDesc', self.IsUnlock and 2 or 1)
        else
            self.TxtTips.gameObject:SetActiveEx(false)
        end
    end

    
end

function XUiPBRGeniusPanelGeniusDetail:OnBtnUnlockClick()
    if self.IsCanUnlock then
        XMVCA.XPBRGame.NetworkAgency:DoPbrProgressionUnlockRequest(self.NodeId, function(success)
            if success then
                XUiManager.TipMsg(self._Control:GetClientPBRText('GeniusUnlockSuccessTips'))
                self:Refresh(self.NodeId)
                self.Parent:Refresh()
            end
        end)
    else
        XUiManager.TipMsg(self.NotDesc)
    end
end

function XUiPBRGeniusPanelGeniusDetail:OnBtnGetClick()

end

return XUiPBRGeniusPanelGeniusDetail
